#include <stdio.h>

int main(void) {
    long long n, total = 0;
    // 读取整分钟时长，使用足够宽的整数类型。
    scanf("%lld", &n);
    // 中间段最多到60分钟，免费15分钟不能一起计费。
    if (n > 15) {
        long long end = n < 60 ? n : 60;
        total += (end - 15) * 2;
    }
    if (n > 60) {
        total += n - 60;
    }
    // 两段费用已经相加，只输出总积分。
    printf("%lld\n", total);
    return 0;
}

