import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        // 读取整分钟时长，使用足够宽的整数类型。
        long n = in.nextLong();
        long total = 0;
        // 中间段最多到60分钟，免费15分钟不能一起计费。
        if (n > 15) {
            total += (Math.min(n, 60) - 15) * 2;
        }
        if (n > 60) {
            total += n - 60;
        }
        // 两段费用已经相加，只输出总积分。
        System.out.println(total);
    }
}

